      "class UndoLogKv{public:bool begin();bool set(const std::string& key,int value);bool erase(const std::string& key);bool commit();bool abort();std::optional<int> get(const std::string& key)const;private:struct Before{std::string key;std::optional<int> value;};bool active_=false;std::map<std::string,int> data_;std::vector<Before> undo_;std::set<std::string> logged_;};",
      "bool UndoLogKv::begin(){if(active_)return false;active_=true;undo_.clear();logged_.clear();return true;}bool UndoLogKv::set(const std::string&k,int v){if(!active_||k.empty())return false;if(logged_.insert(k).second){auto it=data_.find(k);undo_.push_back({k,it==data_.end()?std::nullopt:std::optional<int>(it->second)});}data_[k]=v;return true;}bool UndoLogKv::erase(const std::string&k){if(!active_||!data_.count(k))return false;if(logged_.insert(k).second)undo_.push_back({k,data_[k]});data_.erase(k);return true;}bool UndoLogKv::commit(){if(!active_)return false;active_=false;undo_.clear();logged_.clear();return true;}bool UndoLogKv::abort(){if(!active_)return false;for(auto it=undo_.rbegin();it!=undo_.rend();++it)if(it->value)data_[it->key]=*it->value;else data_.erase(it->key);active_=false;undo_.clear();logged_.clear();return true;}std::optional<int>UndoLogKv::get(const std::string&k)const{auto it=data_.find(k);return it==data_.end()?std::nullopt:std::optional<int>(it->second);}",
