      "MvccStore::Snapshot MvccStore::snapshot()const{return version_;}bool MvccStore::commit(const std::string&k,int v){if(k.empty()||version_==LLONG_MAX)return false;versions_[k].push_back({++version_,v});return true;}std::optional<int>MvccStore::read(const std::string&k,Snapshot s)const{if(s<0||s>version_)return std::nullopt;auto it=versions_.find(k);if(it==versions_.end())return std::nullopt;auto p=std::upper_bound(it->second.begin(),it->second.end(),std::pair<long long,int>{s,INT_MAX});return p==it->second.begin()?std::nullopt:std::optional<int>(std::prev(p)->second);}",
