      "LockOrderTransfer t;check(t.add(9,10)&&t.add(2,0)&&t.transfer(9,2,4));check(t.balance(9)==6&&t.balance(2)==4&&t.lock_plans()==std::vector<std::pair<int,int>>{{2,9}});",
