      "bool TwoPhaseResources::add(const std::string&p,int c){return !p.empty()&&c>=0&&capacity_.emplace(p,c).second;}int TwoPhaseResources::transact(const std::map<std::string,int>&d){if(d.empty())return -1;for(const auto&e:d)if(e.second<0||!capacity_.count(e.first)||used_[e.first]>capacity_[e.first]-e.second)return 0;for(const auto&e:d)used_[e.first]+=e.second;return 1;}int TwoPhaseResources::used(const std::string&p)const{auto it=used_.find(p);return it==used_.end()?0:it->second;}",
